-- FULL DATABASE SCRIPT for PostgreSQL / pgAdmin
-- Step 1: Create database course_manager_sln in pgAdmin (or run separately while
-- connected to the postgres database):
-- CREATE DATABASE course_manager_sln;
-- Step 2: In pgAdmin, connect to course_manager_sln, open Query Tool, and run
-- this entire file. The app uses EnsureCreated(), so the names/types below
-- match the EF Core model.

CREATE TABLE IF NOT EXISTS public.course_categories (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" character varying(100) NOT NULL,
    "Description" character varying(500),
    CONSTRAINT "AK_course_categories_Name" UNIQUE ("Name")
);

CREATE TABLE IF NOT EXISTS public.courses (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" character varying(150) NOT NULL,
    "TuitionFee" numeric(14,2) NOT NULL CHECK ("TuitionFee" > 0),
    "Duration" integer NOT NULL CHECK ("Duration" BETWEEN 1 AND 10000),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "Description" character varying(2000),
    "CourseCategoryId" integer NOT NULL,
    CONSTRAINT "FK_courses_course_categories_CourseCategoryId"
        FOREIGN KEY ("CourseCategoryId")
        REFERENCES public.course_categories ("Id")
        ON DELETE RESTRICT,
    CONSTRAINT "uk_course_name_category" UNIQUE ("Name", "CourseCategoryId")
);

CREATE TABLE IF NOT EXISTS public.course_images (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ImageUrl" character varying(1000) NOT NULL,
    "IsThumbnail" boolean NOT NULL DEFAULT FALSE,
    "CourseId" integer NOT NULL,
    CONSTRAINT "FK_course_images_courses_CourseId"
        FOREIGN KEY ("CourseId")
        REFERENCES public.courses ("Id")
        ON DELETE CASCADE
);

-- Three categories
INSERT INTO public.course_categories ("Id", "Name", "Description") VALUES
    (1, 'Lập trình Web', 'Frontend và backend web'),
    (2, 'Khoa học dữ liệu', 'Phân tích và xử lý dữ liệu'),
    (3, 'Thiết kế', 'Thiết kế giao diện và trải nghiệm')
ON CONFLICT ("Id") DO NOTHING;

