-- Keep identity counters ready for rows added by the application later.
SELECT setval(pg_get_serial_sequence('public.course_categories', 'Id'),
              GREATEST(COALESCE((SELECT MAX("Id") FROM public.course_categories), 1), 1), true);
SELECT setval(pg_get_serial_sequence('public.courses', 'Id'),
              GREATEST(COALESCE((SELECT MAX("Id") FROM public.courses), 1), 1), true);
SELECT setval(pg_get_serial_sequence('public.course_images', 'Id'),
              GREATEST(COALESCE((SELECT MAX("Id") FROM public.course_images), 1), 1), true);
